# Standard library
import uuid

# Third-party
from sqlalchemy import func
from sqlalchemy.orm import Mapped, mapped_column

# Local application
from app.core.base import Base, ReferenceWithFactorMixin


class CoreRefAchievementScope(Base, ReferenceWithFactorMixin):
    __tablename__ = "core_ref_achievement_scope"

    id: Mapped[uuid.UUID] = mapped_column(
        primary_key=True,
        server_default=func.gen_random_uuid(),
        description=(
            "Primary key UUID, auto-generated by the database using "
            "gen_random_uuid(). Uniquely identifies an achievement scope that "
            "defines the evaluation boundary (e.g. single track, trip, "
            "lifetime)."
        ),
    )
